'use strict';
(()=>{
 const $=id=>document.getElementById(id),VM=GeoRadarViewModel;let map,currentUser=null,opened=null,restoring=false,nextOffset=null;
 const embedded=window.parent!==window;
 const section=document.createElement('section');section.className='save-controls';section.innerHTML='<div class="divider"></div><h3>Speichern und wieder öffnen</h3><button id="view-save-open" class="outline" disabled>Ansicht speichern</button><p id="web-account-state" class="micro" role="status">Anmeldung wird geprüft …</p><div class="save-actions"><button id="web-login-open" class="subtle">Anmelden</button><button id="web-logout" class="subtle" hidden>Abmelden</button></div><p id="snapshot-notice" class="micro saved-notice" hidden></p><details id="saved-evaluations"><summary>Gespeicherte Auswertungen</summary><button id="saved-refresh" class="subtle">Übersicht laden</button><div id="saved-list"></div><button id="saved-more" class="subtle" hidden>Weitere laden</button></details>';
 document.querySelector('.analysis-controls').after(section);
 const login=document.createElement('dialog');login.id='login-dialog';login.innerHTML='<div class="dialog-top"><h2>Private Web-Anmeldung</h2><button id="web-login-close" class="icon-button" aria-label="Anmeldung schließen">×</button></div><p>Mit einem bestätigten Benutzerkonto dieses Supabase-Projekts anmelden. Der Supabase-Projektzugang ist ein separates Konto. Sitzungen laufen nach spätestens einer Stunde ab.</p><form id="web-login-form" autocomplete="off"><label for="web-email">E-Mail</label><input id="web-email" type="email" required maxlength="320" autocomplete="off"><label for="web-password">Passwort</label><input id="web-password" type="password" required maxlength="1024" autocomplete="off"><button id="web-login-submit" class="outline" type="submit">Anmelden</button></form><p id="web-auth-feedback" class="micro" role="status"></p><p class="micro">Noch kein Konto? Der Projektadministrator kann es unter Supabase → Authentication → Users anlegen. Keine API-Schlüssel hier eingeben.</p>';document.body.append(login);
 const dialog=document.createElement('dialog');dialog.id='save-dialog';dialog.innerHTML='<div class="dialog-top"><h2>Ansicht speichern</h2><button id="view-save-close" class="icon-button" aria-label="Speichern schließen">×</button></div><label for="view-name">Individueller Name</label><input id="view-name" maxlength="160" placeholder="Zum Beispiel Pumpen-Leads November"><label for="view-kind">Was möchten Sie speichern?</label><select id="view-kind"><option value="view">Kartenansicht speichern</option><option value="research">Recherche einschließlich Kartenansicht speichern</option><option value="image">Kartenansicht als PNG oder PDF exportieren</option></select><p id="view-kind-note" class="micro"></p><p class="micro">Importierte PLZ-Polygondateien werden nicht mitgespeichert. Bitte separat aufbewahren und bei Bedarf erneut laden.</p><div class="save-actions"><button id="view-persist" class="outline">Privat speichern</button><button id="view-png" class="outline" hidden>PNG herunterladen</button><button id="view-pdf" class="outline" hidden>PDF herunterladen</button></div><p id="save-feedback" class="micro" role="status"></p><a id="saved-direct-link" hidden></a>';document.body.append(dialog);
 async function api(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json',...(options.method?{'Content-Type':'application/json','X-GeoRadar-Request':'1'}:{}),...options.headers},signal:AbortSignal.timeout(25000)});let data;try{data=await response.json();}catch{throw Error('Der private Speicherdienst ist in dieser Ansicht nicht verfügbar.');}if(!response.ok){if(response.status===401){currentUser=null;accountState();}throw Error(data.message||'Anfrage fehlgeschlagen.');}return data;}
 function accountState(){
  $('web-account-state').textContent=currentUser?'Angemeldet: '+currentUser.email+' · Auswertungen nur für dieses Konto sichtbar.':embedded?'Private Speicherung ist in der eigenständigen GeoRadar-Webseite verfügbar.':'Private, geräteübergreifende Speicherung erfordert eine Anmeldung.';
  $('web-login-open').hidden=!!currentUser||embedded;$('web-logout').hidden=!currentUser;$('saved-refresh').disabled=!currentUser;$('saved-more').hidden=true;if(!currentUser)$('saved-list').replaceChildren();
  if(embedded&&!$('standalone-save-link')){const link=document.createElement('a');link.id='standalone-save-link';link.href='https://mangold-georadar.vercel.app/';link.target='_blank';link.rel='noopener noreferrer';link.textContent='GeoRadar-Webseite öffnen';$('web-account-state').after(link);}
 }
 async function list(reset=true){if(!currentUser)return;if(reset)$('saved-list').replaceChildren();try{const data=await api('/api/views?offset='+(reset?0:nextOffset||0));for(const row of data.items){const item=document.createElement('div'),name=document.createElement('b'),info=document.createElement('small'),open=document.createElement('a');item.className='saved-view-row';name.textContent=row.name;info.textContent=new Date(row.createdAt).toLocaleString('de-DE')+' · '+(row.kind==='research'?row.recordCount+' Firmen · fester Datenstand':'Kartenansicht');open.href=row.url;open.textContent='Öffnen';item.append(name,info,open);$('saved-list').append(item);}if(reset&&!data.items.length)$('saved-list').textContent='Noch keine Auswertungen für dieses Konto gespeichert.';nextOffset=data.nextOffset;$('saved-more').hidden=nextOffset===null;}catch(e){$('saved-list').textContent=e.message;}}
 function snapshotNotice(changed=false){if(!opened)return;$('snapshot-notice').hidden=false;$('snapshot-notice').textContent=(changed?'Arbeitsdaten geändert. Der gespeicherte Datenstand bleibt unverändert. ':'Gespeicherter Datenstand: ')+opened.name+' · '+new Date(opened.createdAt).toLocaleString('de-DE')+(opened.kind==='research'?' · '+opened.recordCount+' Firmen · Prüfsumme '+opened.dataDigest.slice(0,12):' · nur Kartenansicht')+'. Erneutes Speichern erstellt eine neue Kennung.';}
 function capture(){if(!map)throw Error('Karte ist noch nicht bereit.');const center=map.getCenter(),layers={};for(const c of document.querySelectorAll('[data-group]'))layers[c.dataset.group]=c.checked;for(const id of VM.layers){const c=$(id);if(c?.type==='checkbox')layers[id]=c.checked;}
  return VM.validate({schema:'mangold-georadar/saved-view/v1',view:{center:[center.lng,center.lat],zoom:map.getZoom(),bearing:map.getBearing(),pitch:map.getPitch()},filters:{country:$('country').value,status:$('company-status').value,search:$('company-search').value,postal:$('postal-prefix').value,representatives:[...$('territory-filter').selectedOptions].map(o=>o.value)},layers,analyses:GeoRadarAnalysis.selection(),analysisActive:GeoRadarAnalysis.isActive(),territories:GeoRadarTerritories.getConfiguration(),...(window.GeoRadarResearchSource?{source:window.GeoRadarResearchSource}:{})});
 }
 async function restore(row){if(!map)throw Error('Karte ist noch nicht bereit.');const state=VM.validate(row.view);restoring=true;try{
  GeoRadarAnalysis.setSelection(state.analyses,false);if(state.territories)GeoRadarTerritories.setConfiguration(state.territories);
  if(row.dataset){GeoRadarCompanies.replace(row.dataset,'Gespeicherte Recherche '+row.name);window.GeoRadarResearchSource={savedViewId:row.id,createdAt:row.createdAt};}
  else if(state.source?.savedViewId){const source=await api('/api/views?id='+encodeURIComponent(state.source.savedViewId));if(source.kind!=='research'||!source.dataset)throw Error('Die referenzierte private Recherche ist nicht verfügbar.');GeoRadarCompanies.replace(source.dataset,'Privater referenzierter Datenstand '+source.name);window.GeoRadarResearchSource={savedViewId:source.id,createdAt:source.createdAt};}
  else if(state.source?.code){const source=await api('/api/research?code='+encodeURIComponent(state.source.code));if(state.source.createdAt&&state.source.createdAt!==source.createdAt)throw Error('Die Datenquelle hat einen anderen Stand. Die Ansicht wurde nicht automatisch mit neuen Daten verknüpft.');GeoRadarCompanies.replace(source.data,'Referenzierte Recherche '+source.code);window.GeoRadarResearchSource={code:source.code,createdAt:source.createdAt};}
  else GeoRadarCompanies.replace({records:[]},'Kartenansicht ohne gespeicherte Recherche');
  $('country').value=state.filters.country;$('country').dispatchEvent(new Event('change'));$('company-status').value=state.filters.status;$('company-status').dispatchEvent(new Event('change'));$('company-search').value=state.filters.search;$('company-search').dispatchEvent(new Event('input'));$('postal-prefix').value=state.filters.postal;$('postal-prefix').dispatchEvent(new Event('input'));
  for(const o of $('territory-filter').options)o.selected=state.filters.representatives.includes(o.value);$('territory-filter').dispatchEvent(new Event('change'));
  for(const [key,checked] of Object.entries(state.layers)){const c=document.querySelector('[data-group="'+key+'"]')||$(key);if(c?.type==='checkbox'){c.checked=checked;c.dispatchEvent(new Event('change'));}}
  map.stop();map.jumpTo(state.view);if(state.analysisActive)GeoRadarAnalysis.run(state.analyses);opened=row;$('view-name').value=row.name;snapshotNotice();
 }finally{restoring=false;}}
 const viewId=new URL(location.href).searchParams.get('view');let pending=viewId;
 async function openPending(){if(!pending||!currentUser||!map)return;try{const row=await api('/api/views?id='+encodeURIComponent(pending));await restore(row);pending=null;}catch(e){$('snapshot-notice').hidden=false;$('snapshot-notice').textContent=e.message;}}
 $('web-login-open').onclick=()=>{login.showModal();$('web-auth-feedback').textContent='';};$('web-login-close').onclick=()=>{login.close();$('web-password').value='';};
 $('web-login-form').onsubmit=async e=>{e.preventDefault();$('web-login-submit').disabled=true;try{const email=$('web-email').value,password=$('web-password').value;$('web-password').value='';const data=await api('/api/auth',{method:'POST',body:JSON.stringify({action:'login',email,password})});currentUser=data.user;accountState();login.close();await list();await openPending();}catch(error){$('web-auth-feedback').textContent=error.message;}finally{$('web-password').value='';$('web-login-submit').disabled=false;}};
 $('web-logout').onclick=async()=>{try{await api('/api/auth',{method:'POST',body:JSON.stringify({action:'logout'})});location.assign('/');}catch(e){$('web-account-state').textContent=e.message;}};
 $('saved-refresh').onclick=()=>list();$('saved-more').onclick=()=>list(false);
 function kindChanged(){const image=$('view-kind').value==='image';$('view-persist').hidden=image;$('view-png').hidden=!image;$('view-pdf').hidden=!image;$('view-kind-note').textContent=image?'Exportiert den sichtbaren Kartenausschnitt mit Status- und Vertreterlegende sowie Quellenangaben. Kein Cloud-Speichern.':$('view-kind').value==='research'?'Privater, unveränderlicher Schnappschuss aller geladenen Firmen plus Filter und Kartenansicht. Filter können nach dem Öffnen erneut geändert werden.':'Speichert Kartenausschnitt, Zoom, Filter, Analyseauswahl und Ebenen. Ohne bestätigte Recherchequelle werden keine Firmendaten mitgespeichert.';}
 $('view-kind').onchange=kindChanged;kindChanged();$('view-save-open').onclick=()=>{dialog.showModal();$('save-feedback').textContent='';$('saved-direct-link').hidden=true;};$('view-save-close').onclick=()=>dialog.close();
 $('view-persist').onclick=async()=>{if(!currentUser){$('save-feedback').textContent='Bitte zuerst über Anmelden ein privates Benutzerkonto verbinden.';return;}$('view-persist').disabled=true;try{const payload={name:$('view-name').value,kind:$('view-kind').value,view:capture(),...($('view-kind').value==='research'?{dataset:GeoRadarCompanies.getSnapshot()}:{})};VM.normalizeSave(payload);const saved=await api('/api/views',{method:'POST',body:JSON.stringify(payload)});if(saved.persisted!==true)throw Error('Speicherung wurde nicht bestätigt.');$('save-feedback').textContent='Privat gespeichert · Kennung '+saved.id+' · '+new Date(saved.createdAt).toLocaleString('de-DE');$('saved-direct-link').href=saved.url;$('saved-direct-link').textContent='Gespeicherte Auswertung öffnen';$('saved-direct-link').hidden=false;await list();}catch(e){$('save-feedback').textContent=e.message;}finally{$('view-persist').disabled=false;}};
 async function mapImage(){if(!map||!map.isStyleLoaded())throw Error('Karte noch nicht vollständig geladen.');await new Promise(resolve=>{map.once('render',resolve);map.triggerRepaint();});const source=map.getCanvas(),canvas=document.createElement('canvas');canvas.width=Math.max(source.width,1200);const mapHeight=Math.round(source.height*canvas.width/source.width);canvas.height=mapHeight+170;const ctx=canvas.getContext('2d');ctx.fillStyle='#0e2337';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0,canvas.width,mapHeight);
  const scale=canvas.width/map.getContainer().clientWidth;if($('office-layer').checked){const p=map.project([9.508511741063957,47.64373714669217]);if(p.x>=0&&p.y>=0&&p.x<map.getContainer().clientWidth&&p.y<map.getContainer().clientHeight){ctx.fillStyle='#154f7b';ctx.fillRect(p.x*scale-12,p.y*scale-12,24,24);ctx.fillStyle='#ffffff';ctx.font='bold 17px Arial';ctx.fillText('M',p.x*scale-7,p.y*scale+7);}}
  ctx.fillStyle='#ffffff';ctx.font='bold 18px Arial';ctx.fillText(($('view-name').value.trim()||'Mangold GeoRadar').slice(0,90)+' · '+new Date().toLocaleString('de-DE'),18,mapHeight+27);ctx.font='13px Arial';ctx.fillText(GeoRadarCompanies.getFilteredRecords().length+' Firmen im aktuellen Filter · gespeicherter/geladener Datenstand, keine Gesamtmarkt-Hochrechnung',18,mapHeight+49);let x=18;
  for(const d of GeoRadarRepresentatives.definitions){ctx.strokeStyle=d.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+7,mapHeight+73,6,0,Math.PI*2);ctx.stroke();ctx.fillText(d.code+' '+d.personnelNumber,x+21,mapHeight+78);x+=100;}
  x=18;for(const d of Object.values(GeoRadarData.statuses)){ctx.fillStyle=d.color;ctx.beginPath();ctx.arc(x+6,mapHeight+101,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff';ctx.fillText(d.label,x+18,mapHeight+106);x+=Math.max(160,ctx.measureText(d.label).width+40);}
  ctx.font='11px Arial';ctx.fillText('© OpenStreetMap contributors · openstreetmap.org/copyright (ODbL) · OpenFreeMap / OpenMapTiles · MapLibre GL JS',18,mapHeight+135);ctx.fillText('Kontextmaske: DeutschlandJSON / Floh Pretti; Statistik Austria (CC BY 4.0) · PLZ-Präfixpunkte: GeoNames (CC BY 4.0)',18,mapHeight+153);return canvas;
 }
 function download(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function fileName(){return ($('view-name').value.trim()||'GeoRadar-Kartenansicht').replace(/[^\p{L}\p{N} _-]/gu,'_').slice(0,120);}
 function pdf(canvas){const bytes=Uint8Array.from(atob(canvas.toDataURL('image/jpeg',.92).split(',')[1]),c=>c.charCodeAt(0)),enc=new TextEncoder(),parts=[],offsets=[0];let length=0;const add=v=>{const b=typeof v==='string'?enc.encode(v):v;parts.push(b);length+=b.length;};const obj=(n,value)=>{offsets[n]=length;add(n+' 0 obj\n'+value+'\nendobj\n');};add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');const w=842,h=595,ratio=Math.min((w-24)/canvas.width,(h-24)/canvas.height),dw=canvas.width*ratio,dh=canvas.height*ratio;obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+w+' '+h+'] /Resources << /XObject << /Img 4 0 R >> >> /Contents 5 0 R >>');offsets[4]=length;add('4 0 obj\n<< /Type /XObject /Subtype /Image /Width '+canvas.width+' /Height '+canvas.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+bytes.length+' >>\nstream\n');add(bytes);add('\nendstream\nendobj\n');const commands='q '+dw+' 0 0 '+dh+' '+((w-dw)/2)+' '+((h-dh)/2)+' cm /Img Do Q';obj(5,'<< /Length '+enc.encode(commands).length+' >>\nstream\n'+commands+'\nendstream');const start=length;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add('trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF');return new Blob(parts,{type:'application/pdf'});}
 $('view-png').onclick=async()=>{try{const canvas=await mapImage(),blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error('PNG-Export nicht möglich.');download(fileName()+'.png',blob);$('save-feedback').textContent='PNG erstellt.';}catch(e){$('save-feedback').textContent=e.message;}};
 $('view-pdf').onclick=async()=>{try{download(fileName()+'.pdf',pdf(await mapImage()));$('save-feedback').textContent='PDF erstellt.';}catch(e){$('save-feedback').textContent=e.message;}};
 document.addEventListener('georadar:companies-updated',()=>{if(opened&&!restoring)snapshotNotice(true);});
 document.addEventListener('georadar:map-ready',event=>{map=event.detail;$('view-save-open').disabled=false;openPending();});
 window.GeoRadarSavedViews={capture,restore,isSignedIn:()=>!!currentUser};
 if(embedded){accountState();return;}
 api('/api/auth').then(async data=>{currentUser=data.user;accountState();await openPending();}).catch(()=>{accountState();if(viewId){$('snapshot-notice').hidden=false;$('snapshot-notice').textContent='Zum Öffnen dieser privaten Auswertung bitte anmelden.';}});
})();
